import os
import tempfile
from pathlib import Path

import pytest

from envcfg import load, ConfigError


def _mk_toml(path: Path, content: str) -> None:
    path.write_text(content)


def _env(prefix: str, **kv) -> dict[str, str]:
    return {f"{prefix}__{k.upper()}": v for k, v in kv.items()}


def test_defaults_only():
    cfg = load({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    with tempfile.TemporaryDirectory() as d:
        p = Path(d) / "c.toml"
        _mk_toml(p, "[x]\ny = 99\n")
        cfg = load({"x": 1, "z": 0}, toml_path=str(p))
        assert cfg == {"x": 99, "y": 99, "z": 0}


def test_toml_nested():
    with tempfile.TemporaryDirectory() as d:
        p = Path(d) / "c.toml"
        _mk_toml(p, "[server]\nport = 8080\n")
        cfg = load({"server": {"port": 80}}, toml_path=str(p))
        assert cfg == {"server": {"port": 8080}}


def test_env_overrides_toml():
    with tempfile.TemporaryDirectory() as d:
        p = Path(d) / "c.toml"
        _mk_toml(p, "[x]\ny = 99\n")
        cfg = load({"x": 1, "z": 0}, toml_path=str(p), prefix="APP", env=_env("APP", x="100", y="200"))
        assert cfg == {"x": 100, "y": 200, "z": 0}


def test_env_nested():
    cfg = load({"server": {"port": 80}}, prefix="APP", env=_env("APP", server_port="9000"))
    assert cfg == {"server": {"port": 9000}}


def test_env_missing_default_raises():
    with pytest.raises(ConfigError) as exc:
        load({}, prefix="APP", env=_env("APP", foo="bar"))
    assert "No default for env var" in str(exc.value)


def test_env_bad_int_raises():
    with pytest.raises(ConfigError) as exc:
        load({"x": 1}, prefix="APP", env=_env("APP", x="notanumber"))
    assert "Bad value for" in str(exc.value)


def test_env_bad_bool_raises():
    with pytest.raises(ConfigError) as exc:
        load({"x": True}, prefix="APP", env=_env("APP", x="maybe"))
    assert "Bad value for" in str(exc.value)


